    mov.u32 %r2, %ntid.x;                // blockDim.x
    mad.lo.s32 %r3, %r1, %r2, %tid.x;    // global thread index (int)
    cvt.u64.u32 %rd4, %r3;               // tid as 64‑bit

    // -------------------------------------------------
    // Compute stride = total number of threads in the grid
    // -------------------------------------------------
    mov.u32 %r4, %nctaid.x;              // gridDim.x
    mad.lo.s32 %r5, %r4, %r2, %r2;       // blockDim.x * gridDim.x
    cvt.u64.u32 %rd5, %r5;               // stride as 64‑bit

    // -------------------------------------------------
    // Main loop: each thread processes elements idx = tid + i*stride
    // -------------------------------------------------
    @!p loop_start;
    setp.ge.u64 %p, %rd4, %rd3;          // if tid >= N, exit
    @%p ret;

loop_start:
    // byte offset = idx * sizeof(__half) (2 bytes)
