    st.global.f16 [%rd8], %f0;

    // idx += stride
    add.u64 %rd4, %rd4, %rd5;
    cvt.u32.u64 %r3, %rd4;               // update 32‑bit index for next iteration

    // continue while idx < N
    setp.lt.u64 %p, %rd4, %rd3;
